nodes.script:
const rows = {{nodes.select-expenses.output}};
const payload = {
  title: "支出明细",
  columns: [
    { key: "spent_at", label: "日期" },
    { key: "category", label: "类别" },
    { key: "amount", label: "金额" },
    { key: "note", label: "备注" },
  ],
  rows: rows.map((r) => ({
    spent_at: r.spent_at,
    category: r.category,
    amount: r.amount,
    note: r.note === null ? "" : r.note,
  })),
};
console.log(JSON.stringify(payload));
